        let text = zone ? `${head} @ ${zone}` : head;
        const off = String(segment.off || "").trim();
        if (off)
            text += `, ${/^\d+\s*(s|sec|secs|m|min|mins)?$/i.test(off) ? `${off} jog` : off}`;
