        const detail = adj.length
            ? `<details class="verified-detail"><summary>what was adjusted</summary>
           <ul class="verified-list">${adj.slice(0, 8).map((a) => `<li>${escHtml(String(a))}</li>`).join("")}</ul>
         </details>`
            : "";
