// ==== public/js/today-plan-surface-renderer.js ====
(() => {
// @ts-check
// Today plan/logging surface renderer: done card, session surface, card ordering,
// pending off-plan cards, finish affordance, and skipped line.
(() => {
    function orderedSurfaceItems(options, deps) {
        if (options.isRunDay || options.cardioItems.length > 1 || (options.cardioItems.length && options.strengthItems.length)) {
            return [
                ...options.activeItems.filter(deps.isCardioItem),
                ...options.activeItems.filter((item) => !deps.isCardioItem(item)),
            ];
        }
        return options.activeItems;
    }
    function pendingPrefill(last) {
        if (!last)
            return { weight: null, reps: null, rir: null, duration_sec: null };
        return {
            weight: last.weight,
            reps: last.reps,
            rir: last.rir,
            duration_sec: last.duration_sec ?? null,
        };
    }
    function buildHtml(options, deps) {
        if (options.showDone) {
            return deps.sessionDoneCard(options.session, options.day, { isToday: options.isToday });
        }
        if (!options.showPlan)
            return "";
        const surfaceDeps = deps.planSurfaceDeps();
        let html = `<div class="plansurface reveal" style="--i:2">`;
        if (!options.focus) {
            html += deps.planSurface.sessionHeadHtml({
                isRunDay: options.isRunDay,
                isToday: options.isToday,
                cardioItems: options.cardioItems,
                day: options.day,
                exDone: options.exDone,
                exTotal: options.exTotal,
                hasSyncedCardioToday: options.hasSyncedCardioToday,
            }, surfaceDeps);
        }
        html += deps.planSurface.daySwitchHtml(options.plan, options.activeDay, surfaceDeps);
        html += deps.planSurface.rxBannerHtml(options.rxByEx, options.activeDay, surfaceDeps);
        const garmin = options.session && typeof options.session === "object" ? options.session.garmin : null;
        if (options.hasGarmin)
            html += deps.garminSessionCard(garmin);
        let cardIdx = 0;
        let syncLineUsed = false;
        for (const item of orderedSurfaceItems(options, deps)) {
            if (deps.isCardioItem(item)) {
                const matched = options.matchedCardio.get(item) || null;
                const line = (!matched && !syncLineUsed) ? options.syncedLine : "";
                if (line)
                    syncLineUsed = true;
                html += deps.cardioPlanCard(item, cardIdx++, matched, line);
                continue;
            }
            const exerciseName = String(item.exercise || "");
            html += deps.exCard({ ...item, fromPlan: true }, options.loggedByEx[exerciseName] || [], options.prefillFor(item), cardIdx++, options.rxFor(exerciseName));
        }
        for (const exercise of options.offPlanEx) {
            const logged = options.loggedByEx[exercise] || [];
            const latest = logged[logged.length - 1];
            html += deps.exCard({ exercise, fromPlan: false }, logged, { weight: latest?.weight, reps: latest?.reps, rir: latest?.rir }, cardIdx++, options.rxFor(exercise));
        }
        for (const pending of options.pendingOffPlan) {
            html += deps.exCard({ exercise: pending.name, fromPlan: false, mode: pending.mode || null }, [], pendingPrefill(options.lastSets[pending.name]), cardIdx++, options.rxFor(pending.name));
        }
        html += deps.planSurface.addExerciseFormHtml();
        if (options.hasLoggedSets) {
            html += deps.planSurface.finishHtml(options.session || {}, { isToday: options.isToday, logDate: options.logDate }, surfaceDeps);
        }
        html += deps.skipLineHtml(options.skippedItems.map((item) => (deps.isCardioItem(item) ? deps.cardioLabel(item) : String(item.exercise || ""))));
        html += `</div>`;
        return html;
    }
    const CAIRN_TODAY_PLAN_SURFACE_RENDERER = {
        buildHtml,
    };
    Object.assign(globalThis, { CairnTodayPlanSurfaceRenderer: CAIRN_TODAY_PLAN_SURFACE_RENDERER });
    if (typeof window !== "undefined") {
        Object.assign(window, { CairnTodayPlanSurfaceRenderer: CAIRN_TODAY_PLAN_SURFACE_RENDERER });
    }
})();
})();
;
// ==== public/js/today-render-state-client.js ====
(() => {
// @ts-check
// Today render-state decisions: derive the high-level visible mode for the day
// before the screen assembles markup.
(() => {
    function derive(input) {
        const hasLoggedSets = !!(input.session && (input.session.sets || []).length);
        const hasPlanDay = !!(input.day?.items || []).length;
        const revealOn = !!(input.planReveal &&
            input.planReveal.date === input.logDate &&
            input.planReveal.on);
        const isFinished = !!(input.session && input.session.finished_at);
        const hasGarmin = !!(input.session && input.session.garmin);
        const showPlan = !input.isToday || hasLoggedSets || hasGarmin || revealOn || input.read?.kind === "train";
        const showDone = isFinished && input.isToday && !revealOn;
        return {
            hasLoggedSets,
            hasPlanDay,
            revealOn,
            isFinished,
            hasGarmin,
            showPlan,
            showDone,
        };
    }
    const CAIRN_TODAY_RENDER_STATE = { derive };
    Object.assign(globalThis, { CairnTodayRenderState: CAIRN_TODAY_RENDER_STATE });
    if (typeof window !== "undefined") {
        Object.assign(window, { CairnTodayRenderState: CAIRN_TODAY_RENDER_STATE });
    }
})();
})();
;
// ==== public/js/today-post-render-wiring.js ====
(() => {
// @ts-check
// Today post-render DOM wiring: quick capture, cardio/apply/date controls,
// and side loader dispatch after the Today HTML swap.
(() => {
    function wirePostRender(deps) {
        deps.updateHeaderCondense();
        deps.runCountUps(deps.root, { snap: deps.soft });
        const quickLogButton = deps.root.querySelector("#qlBtn");
        const quickLogInput = deps.root.querySelector("#qlInput");
        quickLogButton?.addEventListener("click", () => deps.quickLog());
        quickLogInput?.addEventListener("keydown", (event) => {
            if (event.key === "Enter")
                deps.quickLog();
        });
        deps.root.querySelectorAll("[data-cardio-log]").forEach((button) => button.addEventListener("click", () => {
            const input = deps.root.querySelector("#qlInput");
            if (!input)
                return;
            input.value = button.dataset.cardioLog || "";
            input.focus();
            try {
                input.setSelectionRange(input.value.length, input.value.length);
            }
            catch { }
            input.scrollIntoView({ behavior: deps.reducedMotion() ? "auto" : "smooth", block: "center" });
        }));
        deps.wireCardioSync(deps.root, () => deps.renderToday({ soft: true }));
        const applyButton = deps.root.querySelector("#rxApplyBtn");
        applyButton?.addEventListener("click", () => {
            const day = Number(applyButton.dataset.rxDay);
            deps.applyDayProgression(applyButton, Number.isFinite(day) ? day : deps.state.day);
        });
        deps.wireBrief(deps.read, { isToday: deps.isToday });
        if (deps.read?._provisional)
            deps.upgradeBriefInPlace(deps.state.logDate, deps.isToday);
        if (deps.showPlan)
            deps.loadTrainingProvenance(deps.isToday);
        deps.loadTableHint();
        deps.setupWeightChip();
        deps.setupVoiceCapture();
        // Frequents ("Usual around now") + the "how are you feeling?" check-in were
        // removed from Today — food variations weren't useful and Chat handles logging
        // and how-you-feel far more naturally (where the user actually does it).
        deps.loadContextBanner();
        if (!deps.conductorLeads)
            deps.loadHealthFocusBanner();
        deps.loadWearable(deps.isToday);
        if (deps.isToday) {
            deps.loadDraftProposals();
        }
        if (!deps.deferRail) {
            if (deps.agenda) {
                deps.runAgendaRail(deps.agenda, deps.agendaGeneric, deps.todayRailDeps());
            }
            else {
                deps.runFallbackRail(deps.isToday, deps.todayRailDeps());
            }
        }
        deps.root.querySelector("#goalLine")?.addEventListener("click", () => deps.activateTab("progress"));
        deps.root.querySelector("#paceOffer")?.addEventListener("click", () => {
            deps.state.chatPrefill = deps.todayCompass.paceOffer?.ask || "";
            deps.activateTab("chat");
        });
        deps.root.querySelector("#backToday")?.addEventListener("click", () => {
            deps.state.logDate = deps.localISO();
            deps.state.day = null;
            deps.state.dayPicked = false;
            deps.renderToday();
        });
        deps.root.querySelectorAll(".daybtn").forEach((button) => button.addEventListener("click", () => {
            deps.state.day = Number(button.dataset.day);
            deps.state.dayPicked = true;
            deps.renderToday();
        }));
    }
    const CAIRN_TODAY_POST_RENDER_WIRING = {
        wirePostRender,
    };
    Object.assign(globalThis, { CairnTodayPostRenderWiring: CAIRN_TODAY_POST_RENDER_WIRING });
    if (typeof window !== "undefined") {
        Object.assign(window, { CairnTodayPostRenderWiring: CAIRN_TODAY_POST_RENDER_WIRING });
    }
})();
})();
;
