    chartCanvas._chartXs = xs;
    const drawBase = () => {
        CairnProgressChartDrawing.drawBase(ctx, model, points, opts, colors, width, height);
    };
    const drawHighlight = (hx, hy, index, pop, withDate) => {
        CairnProgressChartDrawing.drawHighlight(ctx, {
            hx,
            hy,
            index,
            pop,
            withDate,
            model,
            points,
            options: opts,
            colors,
            width,
            height,
            formatValue: fmtVal,
        });
    };
